StructuredTextModel.Text:
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:						PID
//	CREATOR:					Helgevold - Daniel Årvik
// REQUIREMENTS: 		NX CPU
// 
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	VERSION			DATE				SIGN						DESCRIPTION
//	1.0.0				2023-03-01			Daniel Årvik				Initial Release
// 2.0.0				2025-03-11			Fredrik Bjerkenes 	Rework
// 2.0.1				2025-10-03			William Veim			Translation and rearrange
//================================================================================================================================
//
//		BESKRIVELSE:
//		Simplifies the use of the PIDAT function by reducing functionality that is not in use (tracking)
// 		and moving parameters to inputs instead of using the structures '_sOPR_SET_PARAMS' and '_sINIT_SET_PARAMS'.
//
//		P term: Lower value → stronger proportional effect, 0.01 to 1000.00 (% FS)
//		I term: Higher value → stronger integral effect, 0s = no integral term up to 10,000s
//		D term: Higher value → stronger derivative effect, 0s = no derivative term up to 10,000s
//
//===============================================================================================================================

//Sets initial parameters
InitSetParameters.SampTime 		:= T#100ms; 			//Default
InitSetParameters.RngUpLmt 		:= RngUpLmt;			//Input
InitSetParameters.RngLowLmt		:= RngLowLmt;		//Input
InitSetParameters.DirOpr 			:= Direction;				//Input

//Sets operational parameters
OprSetParameters.MVLowLmt 	:= MVLowLmt; 		//Input
OprSetParameters.MVUpLmt 		:= MVUpLmt; 			//Input
OprSetParameters.ErrorMV 		:= FB_PID.MV; 				//Input (Hold output in case of fault)
OprSetParameters.ManResetVal 	:= 0.0;	 					//Input
OprSetParameters.StopMV 			:= 0.0; 						//Default
OprSetParameters.Alpha 			:= 0.65; 					//Default
OprSetParameters.ATCalcGain 	:= 1.0; 						//Default
OprSetParameters.ATHystrs 		:= 0.2; 						//Default
OprSetParameters.MVTrackSw	:= FALSE;					//Tracking not in use
OprSetParameters.MVTrackVal 	:= 0.0; 						//Tracking not in use

//Convert integration and derivation( UINT to TIME)
Integration_Band_Time:= 	SecToTime(In:=Inp_IntergrationTime);
Derivation_Band_Time	:= 	SecToTime(In:=Inp_DerivationTime);

TON_InitialCycle(In:=TRUE, PT:=TIME#100ms);

IF TON_InitialCycle.Q AND NOT Inp_ManualControl THEN
	Wrk_ManualValue:=	FB_PID.MV;
ELSIF Inp_ManualControl THEN
	Wrk_ManualValue:=	Inp_ManualValue;
END_IF;

//Excecuting PID control
FB_PID(
  Run 							:= ENS, //Start PID regulator
  ManCtl						:= (NOT TON_InitialCycle.Q AND Cfg_RetainOutput) OR Inp_ManualControl, //Start manual control (also used for retain output)
  StartAT						:= Autotune_Start, //Start autotuning
  PV				 				:= ProcessValue, //Prosess Value input
  SP 								:= SetpointValue, //Settpunkt Value input
  OprSetParams 			:= OprSetParameters, //Setup parameter register
  InitSetParams 			:= InitSetParameters, //Initial parameter register
  ProportionalBand 		:= Inp_Proportional_Band, //P-Band
  IntegrationTime 		:= Integration_Band_Time, //I-Time
  DerivativeTime 			:= Derivation_Band_Time, //D-Time
  ManMV 						:= Wrk_ManualValue, //Manual value (Used for retain output)
  Error 							=> Fault, //Fault PID controller 
  MV 							=> Output, //Gain
  ATDone						=>Autotune_Done, //Autotuning done
  ATBusy						=>Autotune_Busy); //Autotuning Busy

//Convert integration time and derivation from TIME to UINT
Inp_IntergrationTime 	:= LINT_TO_UINT(TimeToSec(Integration_Band_Time));
Inp_DerivationTime 	:= LINT_TO_UINT(TimeToSec(Derivation_Band_Time));

IF Autotune_Start AND Autotune_Done THEN
	Autotune_Start:=FALSE;
END_IF;
